python3 - <<'EOF'
import numpy as np
from scipy.optimize import curve_fit
raw=open('/app/graphene.dat').read()
vals=np.array([float(s.replace(',','.')) for s in raw.split()])
x=vals[0::2]; y=vals[1::2]
idx=np.argsort(x); xs=x[idx]; ys=y[idx]

def lor(x,x0,g,A,off): return off + A*g*g/((x-x0)**2+g*g)
def lorlin(x,x0,g,A,c,m): return c+m*(x-x0) + A*g*g/((x-x0)**2+g*g)
def gau(x,x0,s,A,off): return off + A*np.exp(-0.5*((x-x0)/s)**2)

def fit(f,lo,hi,p0,ymax=None):
    m=(xs>=lo)&(xs<=hi)
    if ymax is not None: m &= (ys<ymax)
    xx=xs[m]; yy=ys[m]
    popt,pcov=curve_fit(f,xx,yy,p0=p0,maxfev=400000)
    resid=yy-f(xx,*popt); r2=1-np.sum(resid**2)/np.sum((yy-yy.mean())**2)
    return popt,np.sqrt(np.abs(np.diag(pcov))),len(xx),r2

print("G wing fits, constant offset, exclude saturated:")
for lo,hi in [(17000,21500),(16500,22000),(17500,21500),(17000,22500)]:
  for ymax in [70000,60000,50000,40000,None]:
    try:
        p,e,n,r2=fit(lor,lo,hi,[19200,900,70000,14000],ymax)
        print(f"  {lo}-{hi} ymax={ymax} n={n} R2={r2:.4f}: x0={p[0]:.1f} g={p[1]:.0f} A={p[2]:.0f} off={p[3]:.0f} | errs {e[0]:.1f},{e[1]:.0f},{e[2]:.0f},{e[3]:.0f}")
    except Exception as ex: print("fail",lo,hi,ymax,ex)
  print()
print("G wing fits, LINEAR baseline:")
for lo,hi in [(16500,22000),(17000,21500),(16000,22500)]:
  for ymax in [70000,50000,None]:
    try:
        p,e,n,r2=fit(lorlin,lo,hi,[19200,900,70000,14000,0],ymax)
        print(f"  {lo}-{hi} ymax={ymax} n={n} R2={r2:.4f}: x0={p[0]:.1f} g={p[1]:.0f} A={p[2]:.0f} c={p[3]:.0f} m={p[4]:.3f}")
    except Exception as ex: print("fail",ex)
